1	// ABI contract for hybrid handoff state: magic/version, layout, roundtrip.
2	
3	#include "hybrid/state_abi.h"
4	
5	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
6	#include <doctest.h>
7	
8	#include <cstdint>
9	#include <cstring>
10	#include <type_traits>
11	
12	TEST_CASE("magic and version are stable wire constants")
13	{
14	  CHECK(HYBRID_STATE_MAGIC == 0x42594841u);
15	  CHECK(HYBRID_STATE_VERSION == 1u);
16	}
17	
18	TEST_CASE("struct is standard-layout, trivially copyable, no tail padding")
19	{
20	  CHECK(std::is_standard_layout_v<hybrid_state_v1>);
21	  CHECK(std::is_trivially_copyable_v<hybrid_state_v1>);
22	  CHECK(sizeof(hybrid_state_v1) % 8 == 0);
23	}
24	
25	TEST_CASE("header field offsets")
26	{
27	  CHECK(offsetof(hybrid_state_v1, magic) == 0);
28	  CHECK(offsetof(hybrid_state_v1, version) == 4);
29	  CHECK(offsetof(hybrid_state_v1, flags) == 8);
30	  CHECK(offsetof(hybrid_state_v1, hart_id) == 12);
31	  CHECK(offsetof(hybrid_state_v1, pc) == 16);
32	  CHECK(offsetof(hybrid_state_v1, priv) == 24);
33	}
34	
35	TEST_CASE("GPR and FPR are 32 * uint64_t each, contiguous")
36	{
37	  hybrid_state_v1 s{};
38	  CHECK(offsetof(hybrid_state_v1, gpr) == 32);
39	  CHECK(sizeof(s.gpr) == 32 * sizeof(uint64_t));
40	  CHECK(offsetof(hybrid_state_v1, fpr) == 32 + 32 * 8);
41	  CHECK(sizeof(s.fpr) == 32 * sizeof(uint64_t));
42	}
43	
44	TEST_CASE("V-extension fields use compile-time MAX_VLEN constant")
45	{
46	  hybrid_state_v1 s{};
47	  CHECK(HYBRID_VLEN_BYTES_MAX >= 16);  // RVV minimum VLEN=128 -> 16 bytes
48	  CHECK((HYBRID_VLEN_BYTES_MAX & (HYBRID_VLEN_BYTES_MAX - 1)) == 0);  // power of 2
49	  CHECK(sizeof(s.vreg) == 32u * HYBRID_VLEN_BYTES_MAX);
50	}
51	
52	TEST_CASE("V CSRs vxsat/vxrm/vcsr follow vreg")
53	{
54	  CHECK(offsetof(hybrid_state_v1, vxsat)
55	        == offsetof(hybrid_state_v1, vreg) + 32u * HYBRID_VLEN_BYTES_MAX);
56	  CHECK(offsetof(hybrid_state_v1, vxrm)
57	        == offsetof(hybrid_state_v1, vxsat) + sizeof(uint64_t));
58	  CHECK(offsetof(hybrid_state_v1, vcsr)
59	        == offsetof(hybrid_state_v1, vxrm) + sizeof(uint64_t));
60	}
61	
62	TEST_CASE("F13: warmup snapshot fields follow vcsr, before reserved")
63	{
64	  CHECK(offsetof(hybrid_state_v1, mcycle_at_measure_start)
65	        == offsetof(hybrid_state_v1, vcsr) + sizeof(uint64_t));
66	  CHECK(offsetof(hybrid_state_v1, minstret_at_measure_start)
67	        == offsetof(hybrid_state_v1, mcycle_at_measure_start) + sizeof(uint64_t));
68	  CHECK(offsetof(hybrid_state_v1, reserved)
69	        == offsetof(hybrid_state_v1, minstret_at_measure_start) + sizeof(uint64_t));
70	}
71	
72	TEST_CASE("F13: warmup snapshot fields zero-init by default (K=0 contract)")
73	{
74	  hybrid_state_v1 s{};
75	  CHECK(s.mcycle_at_measure_start == 0);
76	  CHECK(s.minstret_at_measure_start == 0);
77	}
78	
79	TEST_CASE("PMP arrays are sized per spec")
80	{
81	  hybrid_state_v1 s{};
82	  CHECK(sizeof(s.pmpcfg) == HYBRID_PMP_CFG_NUM * sizeof(uint64_t));
83	  CHECK(sizeof(s.pmpaddr) == HYBRID_PMP_ADDR_NUM * sizeof(uint64_t));
84	  CHECK(HYBRID_PMP_ADDR_NUM == 64);
85	  CHECK(HYBRID_PMP_CFG_NUM == 16);
86	}
87	
88	TEST_CASE("trailing reserved padding leaves room for v1 future growth")
89	{
90	  hybrid_state_v1 s{};
91	  // 256 bytes were originally reserved; vxsat/vxrm/vcsr consume 24 of them
92	  // without changing the total struct size. The remainder must still hold
93	  // a few more uint64 slots before v2 is required.
94	  CHECK(sizeof(s.reserved) >= 64);
95	  CHECK(sizeof(s.reserved) % 8 == 0);
96	}
