98	TEST_CASE("byte-level roundtrip via memcpy preserves all fields")
99	{
100	  hybrid_state_v1 src{};
101	  src.magic = HYBRID_STATE_MAGIC;
102	  src.version = HYBRID_STATE_VERSION;
103	  src.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP | HYBRID_FLAG_V;
104	  src.hart_id = 1;
105	  src.pc = 0x80001234ULL;
106	  src.priv = 3;  // M-mode
107	
108	  for (int i = 0; i < 32; ++i) {
109	    src.gpr[i] = 0xCAFE0000ULL + i;
110	    src.fpr[i] = 0xF00D0000ULL + i;
111	  }
112	  src.mstatus = 0xa00040080ULL;
113	  src.mepc    = 0x80002000ULL;
114	  src.mtvec   = 0x80000000ULL;
115	  src.satp    = 0x8000000000080000ULL;
116	  src.vstart  = 0;
117	  src.vtype   = 0xc0;
118	  src.vl      = 4;
119	  src.vlenb   = 16;
120	  src.vxsat   = 1;
121	  src.vxrm    = 2;
122	  src.vcsr    = 0x5;  // vxrm[2:1] | vxsat[0]
123	  for (size_t i = 0; i < sizeof(src.vreg); ++i) src.vreg[i] = (uint8_t) i;
124	
125	  alignas(hybrid_state_v1) unsigned char buf[sizeof(hybrid_state_v1)];
126	  std::memcpy(buf, &src, sizeof(src));
127	  hybrid_state_v1 dst{};
128	  std::memcpy(&dst, buf, sizeof(dst));
129	
130	  CHECK(dst.magic == HYBRID_STATE_MAGIC);
131	  CHECK(dst.version == HYBRID_STATE_VERSION);
132	  CHECK(dst.flags == src.flags);
133	  CHECK(dst.hart_id == 1);
134	  CHECK(dst.pc == 0x80001234ULL);
135	  CHECK(dst.priv == 3);
136	  for (int i = 0; i < 32; ++i) {
137	    CHECK(dst.gpr[i] == 0xCAFE0000ULL + i);
138	    CHECK(dst.fpr[i] == 0xF00D0000ULL + i);
139	  }
140	  CHECK(dst.mstatus == 0xa00040080ULL);
141	  CHECK(dst.mepc == 0x80002000ULL);
142	  CHECK(dst.mtvec == 0x80000000ULL);
143	  CHECK(dst.satp == 0x8000000000080000ULL);
144	  CHECK(dst.vtype == 0xc0);
145	  CHECK(dst.vl == 4);
146	  CHECK(dst.vlenb == 16);
147	  CHECK(dst.vxsat == 1);
148	  CHECK(dst.vxrm == 2);
149	  CHECK(dst.vcsr == 0x5);
150	  CHECK(std::memcmp(dst.vreg, src.vreg, sizeof(src.vreg)) == 0);
151	}
