1	// Wire contract between the QEMU TCG plugin and vsim. Both sides write/read
2	// `struct hybrid_state_v1` byte-for-byte through a shared file.
3	//
4	// Stability: never repurpose offsets within a published version. Add new
5	// fields by consuming bytes from `reserved`, or by introducing v2 alongside.
6	//
7	// Endianness: multi-byte fields are little-endian (native on RV64 + x86-64
8	// host). The format is not endian-portable; cross-endian use would need an
9	// explicit byte-swap path.
10	//
11	// C and C++ both compile this header.
12	
13	#ifndef HYBRID_STATE_ABI_H
14	#define HYBRID_STATE_ABI_H
15	
16	#include <stdint.h>
17	#include <stddef.h>
18	
19	#ifdef __cplusplus
20	extern "C" {
21	#endif
22	
23	#define HYBRID_STATE_MAGIC   0x42594841u  // 'AHYB' little-endian
24	#define HYBRID_STATE_VERSION 1u
25	
26	#define HYBRID_FLAG_RV64 (1u << 0)
27	#define HYBRID_FLAG_FP   (1u << 1)
28	#define HYBRID_FLAG_V    (1u << 2)
29	
30	// VLEN upper bound, in bytes. Source of truth: data/configs/ax45mpv_premium.cfg
31	// which sets `NDS_VLEN 512` (-> 64 bytes per vector register). When that
32	// configured value changes, this constant must be updated in lock-step so
33	// the wire-format struct grows or shrinks to match the configured RVV width.
34	#define HYBRID_VLEN_BYTES_MAX 64
35	
36	// 64 PMP entries; pmpcfg slots reserved at 16 so the layout works for both
37	// RV64 (8 entries/CSR) and a future RV32 (4 entries/CSR) packing.
38	#define HYBRID_PMP_CFG_NUM  16
39	#define HYBRID_PMP_ADDR_NUM 64
40	
41	// All fields are naturally 8-byte aligned, so __attribute__((packed)) is
42	// unnecessary and would force unaligned access codegen. Layout is locked by
43	// the static_asserts in state_abi_check.h.
44	struct hybrid_state_v1 {
45	  uint32_t magic;
46	  uint32_t version;
47	  uint32_t flags;
48	  uint32_t hart_id;
49	  uint64_t pc;
50	  uint64_t priv;  // 0=U, 1=S, 3=M
51	
52	  uint64_t gpr[32];
53	  uint64_t fpr[32];
54	
55	  uint64_t mstatus;
56	  uint64_t mepc;
57	  uint64_t mtvec;
58	  uint64_t mcause;
59	  uint64_t mtval;
60	  uint64_t mscratch;
61	  uint64_t medeleg;
62	  uint64_t mideleg;
63	  uint64_t mip;
64	  uint64_t mie;
65	  uint64_t mcycle;
66	  uint64_t minstret;
67	  uint64_t satp;
68	
69	  uint64_t pmpcfg[HYBRID_PMP_CFG_NUM];
70	  uint64_t pmpaddr[HYBRID_PMP_ADDR_NUM];
71	
72	  uint64_t vstart;
73	  uint64_t vtype;
74	  uint64_t vl;
75	  uint64_t vlenb;
76	  uint8_t  vreg[32 * HYBRID_VLEN_BYTES_MAX];
77	  uint64_t vxsat;
78	  uint64_t vxrm;
79	  uint64_t vcsr;
80	
81	  // F13: warmup-window snapshot of cycle/instret counters, captured K insns
82	  // after vsim entry. Drain-only metadata; ResumeDriver never restores them.
83	  // Both zero when --vsim-warmup-icount=0 or the workload exited inside the
84	  // warmup window. Consumes 16 bytes from the original 232-byte reserved tail.
85	  uint64_t mcycle_at_measure_start;
86	  uint64_t minstret_at_measure_start;
87	
88	  uint8_t  reserved[216];  // zero-initialise on write; 256 - 3*8 (vxsat/vxrm/vcsr) - 2*8 (warmup)
89	};
90	
91	#ifdef __cplusplus
92	}  // extern "C"
93	#endif
94	
95	#include "hybrid/state_abi_check.h"
96	
97	#endif  // HYBRID_STATE_ABI_H
